alter table wash_private.catalog_keys add column metadata jsonb not null default '{}';
update wash_private.catalog_keys k set metadata=x->'metadata' from jsonb_array_elements('[{"key":"A_1a","metadata":{"title":"En establecimientos de atención primaria, abastecimiento mejorado de agua corriente en el establecimiento o en el predio.","module":"water"}},{"key":"A_1b","metadata":{"title":"En establecimientos de atención secundaria o terciaria, abastecimiento mejorado de agua corriente en el establecimiento.","module":"water"}},{"key":"A_2","metadata":{"title":"Todos los grifos están conectados a un abastecimiento de agua en funcionamiento, sin fugas en las tuberías ni en los puntos ciegos.","module":"water"}},{"key":"A_3","metadata":{"title":"El agua está disponible durante todas las horas de funcionamiento del establecimiento.","module":"water"}},{"key":"A_4","metadata":{"title":"El servicio de agua está disponible durante todo el año; no se ve afectado por las estaciones, los fenómenos climáticos extremos ni otras limitaciones.","module":"water"}},{"key":"A_5","metadata":{"title":"El sistema principal de suministro de agua ha funcionado durante los últimos 3 meses sin averías importantes","module":"water"}},{"key":"A_6","metadata":{"title":"Se han identificado fuentes adicionales de agua de calidad adecuada, a las que puede accederse si la fuente principal deja de funcionar o no está disponible.","module":"water"}},{"key":"A_7","metadata":{"title":"Hay agua en cantidad suficiente para todos los usos.","module":"water"}},{"key":"A_8","metadata":{"title":"El almacenamiento de agua es seguro, está protegido frente a fenómenos climáticos extremos y es suficiente para cubrir las necesidades del establecimiento durante dos días.","module":"water"}},{"key":"A_9","metadata":{"title":"Cuando la precipitación es suficiente y regular, existen uno o más sistemas de captación de agua de lluvia (con almacenamiento seguro) en buen funcionamiento.","module":"water"}},{"key":"A_10","metadata":{"title":"Se utilizan estrategias de ahorro de agua para reducir el desperdicio de agua.","module":"water"}},{"key":"A_11","metadata":{"title":"El agua potable tiene un nivel aceptable de cloro residual (≥ 0,2 mg/L o ≥ 0,5 mg/L en emergencias) o 0 E. coli por 100 mL.","module":"water"}},{"key":"A_12","metadata":{"title":"El abastecimiento de agua presenta un riesgo nulo o bajo para la salud pública, según la escala de valoración de la inspección sanitaria y la ausencia de E. coli en 100 mL.","module":"water"}},{"key":"A_13","metadata":{"title":"El agua que recibe el establecimiento es tratada y controlada por las autoridades municipales, mediante una gestión de agua segura, o se trata regularmente dentro del establecimiento.","module":"water"}},{"key":"A_14","metadata":{"title":"El abastecimiento de agua del establecimiento (primario, de respaldo y suplementario) es sometido a pruebas sistemáticamente por un funcionario o entidad independiente (por ejemplo, el organismo de vigilancia).","module":"water"}},{"key":"A_15","metadata":{"title":"Se cuenta con una estación de agua potable accesible para el personal, los pacientes y los cuidadores en todo momento y en:\n- las principales áreas de espera o entrada a cada sala\n- en todas las habitaciones donde los pacientes pernoctan o reciben atención especializada.","module":"water"}},{"key":"A_16","metadata":{"title":"En hospitales y establecimientos con servicios para pacientes hospitalizados, se dispone, como mínimo, de una ducha o instalaciones para bañarse por cada 40 pacientes hospitalizados o por sala (el que sea menor), funcionando y accesible.","module":"water"}},{"key":"A_17","metadata":{"title":"En el área de trabajo de parto y parto, hay una ducha o espacio de aseo funcional para las mujeres, privado y con cerradura.","module":"water"}},{"key":"S_1","metadata":{"title":"El establecimiento tiene inodoros (o letrinas mejoradas, que, para generalizar, llamaremos \"inodoros\") para los pacientes, disponibles y utilizables.","module":"sanitation"}},{"key":"S_2","metadata":{"title":"El establecimiento tiene un número suficiente de inodoros disponibles y utilizables para los pacientes.","module":"sanitation"}},{"key":"S_3","metadata":{"title":"Todos los inodoros tienen una estación que funciona para el lavado de las manos en un radio de 5 metros.","module":"sanitation"}},{"key":"S_4","metadata":{"title":"Por lo menos debe disponerse de un inodoro para el personal y los inodoros deben estar claramente separados indicando que son para el personal.","module":"sanitation"}},{"key":"S_5","metadata":{"title":"Los inodoros están claramente separados para hombres y mujeres o, si son mixtos, deben proporcionar privacidad (es decir, compartimientos individuales).","module":"sanitation"}},{"key":"S_6","metadata":{"title":"Existe al menos un inodoro funcional con los artículos necesarios para la higiene menstrual.","module":"sanitation"}},{"key":"S_7","metadata":{"title":"Por lo menos existe un inodoro que funciona para personas con movilidad reducida.","module":"sanitation"}},{"key":"S_8b","metadata":{"title":"Los lodos fecales están totalmente contenidos, posteriormente son vaciados y tratados fuera del establecimiento o localmente.\nEl efluente líquido está totalmente almacenado, o fluye a la tierra desde el fondo del contenedor a un pozo seco o a un sistema de drenaje cerrado.","module":"sanitation"}},{"key":"S_9a","metadata":{"title":"Los inodoros están conectados a un sistema de alcantarillado público y no tienen fugas. La alcantarilla transporta las excretas y las aguas residuales para su tratamiento con un mínimo de fugas y sin que se desborden.","module":"sanitation"}},{"key":"S_9b","metadata":{"title":"Los lodos fecales del contenedor son vaciados periódicamente sin derrames por personal capacitado, con equipo de protección apropiado y (a) se transportan a otro lugar para su tratamiento o (b) se entierran de manera segura localmente.","module":"sanitation"}},{"key":"S_10a","metadata":{"title":"La planta de tratamiento está diseñada y gestionada para proporcionar por lo menos un tratamiento secundario y funciona de acuerdo con normas adecuadas con registros de funcionamiento públicamente disponibles.","module":"sanitation"}},{"key":"S_10b","metadata":{"title":"Se utilizan plantas de tratamiento de lodos fecales bien diseñadas, con registros a disposición del público cuando el tratamiento se lleva a cabo en otro lugar.","module":"sanitation"}},{"key":"S_11","metadata":{"title":"Existe un sistema para drenar las aguas pluviales y las aguas grises que las desvía hacia una zona con buen drenaje o de lixiviación.","module":"sanitation"}},{"key":"S_12","metadata":{"title":"Se captan y reutilizan las aguas grises o pluviales para lavado, limpieza, riego de plantas y descarga del inodoro.","module":"sanitation"}},{"key":"S_13","metadata":{"title":"Solo si hay un sistema de aguas grises, las aguas grises de fregaderos y lavaderos se captan de forma segura y se conducen al alcantarillado, a un campo de lixiviación, a un pozo de absorción o a desagües cerrados sin conexiones cruzadas con el suministro de agua potable.","module":"sanitation"}},{"key":"RES_1","metadata":{"title":"En los lugares donde se generan residuos hay recipientes funcionales y cercanos para recolectar por separado residuos no infecciosos (generales), infecciosos y objetos punzocortantes.","module":"waste"}},{"key":"RES_2","metadata":{"title":"Se realiza una separación adecuada de residuos en todos los lugares donde se generan.","module":"waste"}},{"key":"RES_3","metadata":{"title":"En todos los lugares donde se generan residuos hay instrucciones y recordatorios claramente visibles para separarlos.","module":"waste"}},{"key":"RES_4","metadata":{"title":"Se dispone de equipo de protección y recursos apropiados para la higiene de las manos de todo el personal que se ocupa de la manipulación, tratamiento y eliminación de residuos.","module":"waste"}},{"key":"RES_5","metadata":{"title":"Existen recordatorios y formación para promover y supervisar el uso racional de los equipos de protección personal (EPP) (por ejemplo, los guantes solo se utilizan cuando está indicado)","module":"waste"}},{"key":"RES_6","metadata":{"title":"Existen estrategias para reducir la cantidad de residuos generados en todo el establecimiento (disminuir la generación de residuos “en la fuente”).","module":"waste"}},{"key":"RES_7","metadata":{"title":"Se separan los residuos reciclables no peligrosos y se envían a plantas municipales de reciclaje.","module":"waste"}},{"key":"RES_8","metadata":{"title":"Se dispone de una zona dedicada de almacenamiento de residuos, rodeada de una valla y segura, con capacidad suficiente para almacenar por separado los residuos infecciosos y los no infecciosos.","module":"waste"}},{"key":"RES_9","metadata":{"title":"Los residuos infecciosos se almacenan como máximo hasta la fecha límite de seguridad (determinado por el clima) antes de su tratamiento o eliminación","module":"waste"}},{"key":"RES_10","metadata":{"title":"El equipo de tratamiento de residuos (incinerador u otro) está en buen estado de mantenimiento, está en operación y tiene capacidad suficiente para los residuos generados.","module":"waste"}},{"key":"RES_11","metadata":{"title":"Se dispone de energía/combustible suficiente para el incinerador u otro método de tratamiento.","module":"waste"}},{"key":"RES_12","metadata":{"title":"Los residuos se recogen para su tratamiento fuera del emplazamiento, de forma segura y periódica y se envían a una instalación de tratamiento de residuos adecuada y autorizada","module":"waste"}},{"key":"RES_13","metadata":{"title":"Se dispone de una fosa en operación para enterrar los residuos/un vertedero de residuos cercado o un sistema municipal de recolección de residuos infecciosos (no peligrosos/generales).","module":"waste"}},{"key":"RES_14","metadata":{"title":"En el ámbito local, cuando existe riesgo de inundación, las fosas se construyen de manera que resistan eventos climáticos y emergencias, incluidas las inundaciones, y existe un lugar para almacenamiento de respaldo.","module":"waste"}},{"key":"RES_15","metadata":{"title":"En el ámbito local, donde se utilizan incineradores, se dispone de fosas especiales para verter la ceniza resultante de la incineración.","module":"waste"}},{"key":"RES_16","metadata":{"title":"En hospitales con salas de parto y pacientes hospitalizados, los residuos anatómicos/patológicos se colocan en una fosa especial para esos fines / se incineran en un crematorio o se entierran en un cementerio.","module":"waste"}},{"key":"RES_17","metadata":{"title":"En hospitales, los residuos farmacéuticos son tratados y eliminados con seguridad por medio de una de las siguientes opciones: en un establecimiento seguro de tratamiento y eliminación centralizado (fuera del hospital) / enviados de regreso al fabricante / enviados a incinerar en hornos de alta temperatura.","module":"waste"}},{"key":"RES_18","metadata":{"title":"Existe una persona capacitada y designada como responsable de la eliminación de residuos de la atención de salud, conforme a las normas profesionales aplicables.","module":"waste"}},{"key":"RES_19","metadata":{"title":"Al personal que maneja o elimina los residuos y a los trabajadores de salud se los vacuna contra la hepatitis B (y se les aplican otras vacunas recomendadas por la normativa nacional).","module":"waste"}},{"key":"RES_20","metadata":{"title":"Cuando aumenta la demanda, se emplean estrategias para tratar residuos adicionales.","module":"waste"}},{"key":"H_1","metadata":{"title":"Se dispone de estaciones en buen funcionamiento para la higiene de las manos en todos los lugares de atención, incluida la sala de partos.","module":"hygiene"}},{"key":"H_2","metadata":{"title":"Se dispone de estaciones en buen funcionamiento para la higiene de las manos en todas las áreas de espera o áreas públicas y en la zona de eliminación de residuos.","module":"hygiene"}},{"key":"H_3","metadata":{"title":"Se exhiben materiales de promoción de la higiene de las manos en todas las salas y áreas de tratamiento, y son claramente visibles.","module":"hygiene"}},{"key":"H_4","metadata":{"title":"Se realizan sistemáticamente actividades para verificar el cumplimiento de la higiene de las manos.","module":"hygiene"}},{"key":"H_5","metadata":{"title":"Se realizan inspecciones periódicas en las salas para verificar la disponibilidad de desinfectante para las manos, jabón, toallas de papel y otros implementos para la higiene de las manos.","module":"hygiene"}},{"key":"L_1","metadata":{"title":"Existe una política o protocolo de limpieza claro, detallado, que se aplica y se le da seguimiento.","module":"cleaning"}},{"key":"L_2","metadata":{"title":"Se lleva un registro de limpieza en las áreas de atención a pacientes, las salas o el establecimiento. La persona encargada de la limpieza lo firma todos los días.","module":"cleaning"}},{"key":"L_3","metadata":{"title":"Los inodoros se limpian al menos una vez al día, y el personal de limpieza firma un registro de limpieza que se expone de forma visible.","module":"cleaning"}},{"key":"L_4","metadata":{"title":"Hay personal de limpieza asignado en la sala/establecimiento disponible todos los días.","module":"cleaning"}},{"key":"L_5","metadata":{"title":"Todo el personal que se ocupa de la limpieza ha recibido capacitación.","module":"cleaning"}},{"key":"L_6","metadata":{"title":"Existen y se aplican normas y procedimientos para mejorar la seguridad ocupacional del personal de limpieza y del que manipula residuos médicos.","module":"cleaning"}},{"key":"L_7","metadata":{"title":"Se dispone de materiales apropiados y en buen estado para la limpieza (detergente, estropajos, baldes, etc.).","module":"cleaning"}},{"key":"L_8","metadata":{"title":"Existe un presupuesto anual para suministros y equipos de limpieza ambiental, suficiente para cubrir todas las necesidades.","module":"cleaning"}},{"key":"L_9","metadata":{"title":"Se dispone de un área para el almacenamiento, preparación y cuidado de equipo y materiales de limpieza (área de servicios de limpieza ambiental), limpia y en buen estado, y se utiliza para esos fines.","module":"cleaning"}},{"key":"L_10","metadata":{"title":"Se dispone de equipo de protección personal (EPP) adecuado en todo momento y en cantidades suficientes para el personal de limpieza.","module":"cleaning"}},{"key":"L_11","metadata":{"title":"Se dispone de personal adicional (por ejemplo, una lista de turnos) y suministros de limpieza adicionales para su despliegue en el centro si aumenta la carga de pacientes.","module":"cleaning"}},{"key":"L_12","metadata":{"title":"Todas las camas tienen cubiertas impermeables sin señales de deterioro (rasgaduras, roturas o agujeros).","module":"cleaning"}},{"key":"L_13","metadata":{"title":"Solo para establecimientos con pacientes hospitalizados: existe una lavandería limpia, en buen estado de mantenimiento y con capacidad para satisfacer la demanda (es decir, para lavar la ropa blanca antes de internar a nuevos pacientes).","module":"cleaning"}},{"key":"L_14","metadata":{"title":"Hay servicios de lavandería con agua caliente a 70–80 °C durante 10 minutos para reprocesar los paños y los cabezales de las mopas. Estos materiales se lavan siempre por separado del resto de textiles hospitalarios sucios.","module":"cleaning"}},{"key":"L_15","metadata":{"title":"Solo para establecimientos con pacientes hospitalizados: los alimentos se manipulan y preparan de manera segura (sobre superficies limpias y con utensilios limpios).","module":"cleaning"}},{"key":"L_16","metadata":{"title":"Solo para establecimientos con pacientes hospitalizados: las alacenas y los alimentos preparados están protegidos de moscas, otros insectos o ratas.","module":"cleaning"}},{"key":"E_1","metadata":{"title":"Hay electricidad de alguna fuente, como la red pública, un generador o energía solar, incluidos los sistemas independientes de cadena de frío del Programa Ampliado de Inmunización (PAI). El suministro funciona correctamente y recibe mantenimiento.","module":"energy"}},{"key":"E_2","metadata":{"title":"Hay energía suficiente para todas las necesidades eléctricas del establecimiento.","module":"energy"}},{"key":"E_3","metadata":{"title":"Donde el agua se obtiene por medio de bombas, hay energía suficiente para bombear el agua.","module":"energy"}},{"key":"E_4","metadata":{"title":"Donde se calienta el agua, hay energía suficiente para calentar el agua.","module":"energy"}},{"key":"E_5","metadata":{"title":"Existe una fuente de energía de respaldo, en buen estado de funcionamiento, con combustible en cantidad adecuada, en caso de que falle la fuente principal.","module":"energy"}},{"key":"E_6","metadata":{"title":"Se utiliza iluminación de bajo consumo de energía, con mejores controles y focos ahorradores de energía.","module":"energy"}},{"key":"E_7","metadata":{"title":"El establecimiento cuenta con un plan de preparativos y respuesta para situaciones de emergencia, con su debida partida presupuestaria.","module":"energy"}},{"key":"E_8","metadata":{"title":"La(s) ducha(s) están bien iluminadas, de día y de noche.","module":"energy"}},{"key":"E_9","metadata":{"title":"Las letrinas están bien iluminadas, de día y de noche.","module":"energy"}},{"key":"E_10","metadata":{"title":"Existe ventilación ambiental suficiente en buen funcionamiento (natural o mecánica) en las áreas de atención a pacientes.","module":"energy"}},{"key":"E_11","metadata":{"title":"En zonas donde la malaria es endémica, las camas tienen mosquiteros tratados con insecticida para proteger a los pacientes de enfermedades transmitidas por mosquitos.","module":"energy"}},{"key":"E_12","metadata":{"title":"Se aplica un sistema de compras sostenibles (aplicando el enfoque del ciclo de vida) en todo el establecimiento.","module":"energy"}},{"key":"E_13","metadata":{"title":"Hay papeleras generales en todas las zonas públicas, se retira regularmente la basura del interior y el exterior de las instalaciones y se procura mejorar y mantener el aspecto estético de las instalaciones mediante pintura, jardinería (plantas) y garantizando que todos los equipos y otros artículos se almacenan de forma segura.","module":"energy"}},{"key":"M_1","metadata":{"title":"El establecimiento cuenta con equipos de gestión de calidad/mejora de la calidad/PCI/ WASH FIT, con puntos focales designados para prevención y control de infecciones, servicios de agua, saneamiento e higiene, etc.","module":"management"}},{"key":"M_2","metadata":{"title":"El establecimiento tiene un punto focal o ingeniero que se ocupa de los servicios de agua, saneamiento e higiene, que cuenta con un programa aprobado de trabajo y tiene apoyo de los altos directivos.","module":"management"}},{"key":"M_3","metadata":{"title":"Se consulta a los grupos de mujeres, personas con discapacidad, pueblos indígenas, otros usuarios y al personal —por ejemplo, enfermería, obstetricia y limpieza— sobre las necesidades de agua, saneamiento e higiene y los diseños tecnológicos. Sus aportes influyen en la elección, ubicación y mantenimiento de la tecnología.","module":"management"}},{"key":"M_4","metadata":{"title":"Existe un organigrama actualizado de la estructura administrativa del establecimiento, donde se incluye al personal de limpieza, claramente visible y legible.","module":"management"}},{"key":"M_5","metadata":{"title":"Todo el personal auxiliar, incluido el de limpieza y el que se ocupa de los residuos, tiene una descripción del puesto clara y por escrito, que describe las responsabilidades de PCI y servicios de agua, saneamiento e higiene.","module":"management"}},{"key":"M_6","metadata":{"title":"Todo el personal auxiliar nuevo, incluido el de limpieza y el que se ocupa de los residuos, recibe capacitación adecuada en WASH/PCI, adaptada a su descripción del puesto.","module":"management"}},{"key":"M_7","metadata":{"title":"Se evalúa periódicamente el desempeño del personal. Se reconoce/recompensa al personal de excelente desempeño y se ofrece apoyo para mejorar al personal que no tiene un buen desempeño.","module":"management"}},{"key":"M_8","metadata":{"title":"Existe un protocolo y un sistema eficaz para operar, mantener y reparar la infraestructura y adquirir insumos para:\n- Limpieza ambiental, adaptada a las distintas áreas de servicio.\n- Manipulación de residuos.\n- Operación y mantenimiento de los servicios de agua y saneamiento.","module":"management"}},{"key":"M_9","metadata":{"title":"Se elabora un presupuesto para cubrir los costos del personal de limpieza y mantenimiento, capacitación en PCI/WASH, bienes consumibles de PCI/WASH (por ejemplo, jabón, cloro) y todas las actividades enumeradas en el protocolo.","module":"management"}},{"key":"M_10","metadata":{"title":"Existe una política de seguridad del paciente en todo el establecimiento para mejorar la calidad de la atención, escrita, actualizada y en ejecución.","module":"management"}},{"key":"M_11","metadata":{"title":"En hospitales, existe una política verde (ecológica) para todo el establecimiento, escrita y en ejecución.","module":"management"}},{"key":"M_12","metadata":{"title":"Se aplica un plan de preparación y respuesta ante emergencias que se actualiza periódicamente. El personal recibe capacitación y realiza simulacros para prepararse, responder y recuperarse de crisis climáticas o de emergencias agravadas por el clima.","module":"management"}}]'::jsonb) x where k.key=x->>'key';
create function wash_private.completion_item(s integer,ok boolean,label text,v text,m text default '',i text default '',field text default '') returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_array(jsonb_build_object('step',s,'complete',coalesce(ok,false),'label',label,'view',v,'module',m,'indicator',i,'field',field))
$$;
create function wash_private.valid_date(v text) returns boolean language plpgsql immutable set search_path='' as $$
begin return v ~ '^\d{4}-\d{2}-\d{2}$' and to_char(v::date,'YYYY-MM-DD')=v;exception when others then return false;end $$;
create function wash_private.number_between(v jsonb,lo numeric,hi numeric) returns boolean language sql immutable set search_path='' as $$
 select case when jsonb_typeof(v)='number' then v::numeric between lo and hi else false end
$$;
create function wash_private.evaluation_checks(e uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ev public.wash_evaluations;g jsonb:='{}';r record;k record;d jsonb;a jsonb;mon jsonb;checks jsonb:='[]';steps jsonb;issues jsonb;hospital boolean;visible boolean;key text;label text;okay boolean;n integer;done integer;
begin
 if not wash_private.account_ready() or not wash_private.read_evaluation(e) then raise exception 'FORBIDDEN' using errcode='42501';end if;
 select * into ev from public.wash_evaluations where id=e;if not found then raise exception 'NOT_FOUND';end if;
 for r in select data from public.wash_records where evaluation_id=e and kind='general' order by case when record_key='general' then 0 else 1 end,updated_at,id loop g:=g||r.data;end loop;
 for key,label in select * from (values ('facilityName','Nombre del establecimiento'),('countryCode','País'),('district','Ciudad'),('level','Nivel de atención'),('type','Tipo de institución'),('setting','Ámbito')) x(k,l) loop
  checks:=checks||wash_private.completion_item(1,length(trim(coalesce(g->>key,'')))>0,label,'general','','',key);
 end loop;
 checks:=checks||wash_private.completion_item(1,wash_private.valid_date(g->>'evaluationDate'),'Fecha de evaluación','general','','','evaluationDate');
 checks:=checks||wash_private.completion_item(1,wash_private.number_between(g->'latitude',-90,90) and wash_private.number_between(g->'longitude',-180,180),'Georreferenciación del establecimiento','general','','','latitude');
 checks:=checks||wash_private.completion_item(1,exists(select 1 from public.wash_participants where evaluation_id=e and active and role='coordinator'),'Coordinador del equipo evaluador','general','','','team');
 checks:=checks||wash_private.completion_item(2,g->>'sanitationSystem' in ('alcantarillado','insitu'),'Sistema de saneamiento','assessment','sanitation','S_7','sanitationSystem');
 hospital:=coalesce(lower(g->>'level') ~ 'segundo|tercer|secundari|terciari',false);
 for k in select cat.* from wash_private.catalog_keys cat where cat.key<>'S_8' order by cat.key loop
  visible:=true;
  if k.key='A_1a' and hospital or k.key='A_1b' and not hospital or k.key in ('A_16','RES_16','RES_17','L_13','L_15','L_16','M_11') and not hospital then visible:=false;end if;
  if k.key in ('S_9a','S_10a') and coalesce(g->>'sanitationSystem','')<>'alcantarillado' or k.key in ('S_8b','S_9b','S_10b') and coalesce(g->>'sanitationSystem','')<>'insitu' then visible:=false;end if;
  if k.key='S_13' and not exists(select 1 from public.wash_records where evaluation_id=e and kind='indicator' and record_key='S_11' and data->'score' in ('1'::jsonb,'2'::jsonb)) then visible:=false;end if;
  if not visible then continue;end if;
  select data into d from public.wash_records where evaluation_id=e and kind='indicator' and record_key=k.key;d:=coalesce(d,'{}');
  label:=coalesce(k.metadata->>'title',k.key);
  okay:=d->'score' in ('0'::jsonb,'1'::jsonb,'2'::jsonb) or length(trim(regexp_replace(coalesce(d->>'notes',''),'[•[:space:]]','','g')))>0;
  checks:=checks||wash_private.completion_item(2,okay,label||': respuesta o justificación','assessment',k.metadata->>'module',k.key,'notes');
  if d->'score' not in ('0'::jsonb,'1'::jsonb) or d->'score' is null then continue;end if;
  for key,label in select * from (values ('problemDesc','Descripción del problema'),('associatedRisks','Riesgos asociados'),('severity','Gravedad'),('likelihood','Probabilidad')) x(k,l) loop
   okay:=case when key in ('severity','likelihood') then wash_private.number_between(d->key,0,10) else length(trim(regexp_replace(coalesce(d->>key,''),'[•[:space:]]','','g')))>0 end;
   checks:=checks||wash_private.completion_item(3,okay,k.key||': '||label,'step3',k.metadata->>'module',k.key,key);
  end loop;
  select data into a from public.wash_records where facility_id=ev.facility_id and kind='action' and data->>'indicator_id'=k.key order by updated_at desc,id desc limit 1;a:=coalesce(a,'{}');
  for key,label in select * from (values ('action','Acción de mejora'),('resources','Recursos necesarios'),('responsible','Responsable'),('targetDate','Plazo'),('cost','Costo estimado (0 si no requiere presupuesto)')) x(k,l) loop
   okay:=case when key='targetDate' then wash_private.valid_date(a->>key) when key='cost' then wash_private.number_between(a->key,0,999999999999) else length(trim(regexp_replace(coalesce(a->>key,''),'[•[:space:]]','','g')))>0 end;
   checks:=checks||wash_private.completion_item(4,okay,k.key||': '||label,'step4',k.metadata->>'module',k.key,key);
  end loop;
  select data into mon from public.wash_records where facility_id=ev.facility_id and kind='monitor' and data->>'editor_indicator_id'=k.key and data->>'team_id'=ev.team_id::text order by updated_at desc,id desc limit 1;
  checks:=checks||wash_private.completion_item(5,wash_private.valid_date(coalesce(mon->'editor_fields'->>'nextReviewDate',mon->>'nextReviewDate')),k.key||': Programar fecha de monitoreo','step5',k.metadata->>'module',k.key,'nextReviewDate');
 end loop;
 for n in 3..5 loop
  if exists(select 1 from jsonb_array_elements(checks) x where (x->>'step')::int=n-1 and not (x->>'complete')::boolean) then
   checks:=checks||wash_private.completion_item(n,false,'Completar primero el paso '||(n-1),case n when 3 then 'assessment' when 4 then 'step3' else 'step4' end);
  end if;
 end loop;
 select coalesce(jsonb_agg(x order by (x->>'step')::int),'[]') into issues from jsonb_array_elements(checks) x where not (x->>'complete')::boolean;
 select jsonb_agg(jsonb_build_object('step',s,'total',(select count(*) from jsonb_array_elements(checks) x where (x->>'step')::int=s),'done',(select count(*) from jsonb_array_elements(checks) x where (x->>'step')::int=s and (x->>'complete')::boolean),'complete',not exists(select 1 from jsonb_array_elements(issues) x where (x->>'step')::int=s)) order by s) into steps from generate_series(1,5) s;
 n:=jsonb_array_length(checks);done:=n-jsonb_array_length(issues);
 return jsonb_build_object('evaluation_id',e,'complete',jsonb_array_length(issues)=0,'percent',case when n=0 then 0 else round(100.0*done/n) end,'steps',steps,'issues',issues);
end $$;
revoke all on function wash_private.evaluation_checks(uuid) from public,anon,service_role;
create function public.wash_evaluation_checks(p_evaluation uuid default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare result jsonb;
begin
 if p_evaluation is not null then return wash_private.evaluation_checks(p_evaluation);end if;
 select coalesce(jsonb_object_agg(id,wash_private.evaluation_checks(id)),'{}') into result from public.wash_evaluations where status<>'validated';return result;
end $$;
revoke all on function public.wash_evaluation_checks(uuid) from public,anon,service_role;
grant execute on function wash_private.evaluation_checks(uuid),public.wash_evaluation_checks(uuid) to authenticated;
revoke all on function wash_private.completion_item(integer,boolean,text,text,text,text,text),wash_private.valid_date(text),wash_private.number_between(jsonb,numeric,numeric) from public,anon,authenticated,service_role;

alter function wash_private.command(text,jsonb,uuid) rename to command_before_completion;
revoke all on function wash_private.command_before_completion(text,jsonb,uuid) from public,anon,authenticated,service_role;
create function wash_private.command(p_command text,p_data jsonb,p_operation uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.wash_evaluations;r public.wash_records;req jsonb;out jsonb;checks jsonb;f uuid;eid uuid;request_data jsonb:=p_data;replay jsonb;
begin
 if not wash_private.account_ready() then raise exception 'ACCOUNT_SETUP_REQUIRED' using errcode='42501';end if;
 if p_command='complete_evaluation' then
  eid:=(p_data->>'evaluation_id')::uuid;
  select facility_id into f from public.wash_evaluations where id=eid;
  if not wash_private.read_evaluation(eid) then raise exception 'FORBIDDEN' using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended(f::text,0));
  select * into ev from public.wash_evaluations where id=eid for update;
  if not (wash_private.admin((select country_id from public.wash_facilities where id=f)) or exists(select 1 from public.wash_participants where evaluation_id=eid and user_id=auth.uid() and active and role='coordinator')) then raise exception 'FORBIDDEN' using errcode='42501';end if;
  select request,result into req,out from public.wash_operations where user_id=auth.uid() and operation_id=p_operation;
  if found then if req<>jsonb_build_object('command',p_command,'data',p_data) then raise exception 'OPERATION_REUSED';end if;return out;end if;
  if ev.version is distinct from (p_data->>'version')::integer then raise exception 'VERSION_CONFLICT' using errcode='40001';end if;
  checks:=wash_private.evaluation_checks(eid);if not (checks->>'complete')::boolean then raise exception 'EVALUATION_INCOMPLETE' using detail=checks::text;end if;
  if ev.status in ('draft','editing') then out:=wash_private.command_before_completion('evaluation_status',jsonb_build_object('evaluation_id',eid,'version',ev.version,'status','review'),gen_random_uuid());ev.version:=(out->>'version')::int;end if;
  if ev.status<>'validated' then out:=wash_private.command_before_completion('evaluation_status',jsonb_build_object('evaluation_id',eid,'version',ev.version,'status','validated'),gen_random_uuid());else out:=to_jsonb(ev);end if;
  insert into public.wash_operations values(auth.uid(),p_operation,jsonb_build_object('command',p_command,'data',p_data),out);
  insert into public.wash_events(facility_id,evaluation_id,actor,operation,target_id,after_data) values(f,eid,auth.uid(),'complete_evaluation',eid,jsonb_build_object('checks',checks,'evaluation',out));return out;
 end if;
 if p_command='evaluation_status' and p_data->>'status'='validated' and not exists(select 1 from public.wash_operations where user_id=auth.uid() and operation_id=p_operation) then
  eid:=(p_data->>'evaluation_id')::uuid;select facility_id into f from public.wash_evaluations where id=eid;
  if not wash_private.read_evaluation(eid) then raise exception 'FORBIDDEN' using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended(f::text,0));checks:=wash_private.evaluation_checks(eid);
  if not (checks->>'complete')::boolean then raise exception 'EVALUATION_INCOMPLETE' using detail=checks::text;end if;
 end if;
 if p_command='save_record' then
  if nullif(p_data->>'id','') is not null then select * into r from public.wash_records where id=(p_data->>'id')::uuid;end if;
  if coalesce(r.kind,p_data->>'kind')='indicator' then
   eid:=coalesce(r.evaluation_id,(p_data->>'evaluation_id')::uuid);select facility_id into f from public.wash_evaluations where id=eid;
   if not wash_private.read_evaluation(eid) then raise exception 'FORBIDDEN' using errcode='42501';end if;
   perform pg_advisory_xact_lock(hashtextextended(f::text,0));
   select request->'data' into replay from public.wash_operations where user_id=auth.uid() and operation_id=p_operation and request->>'command'=p_command;
   if found then
    if replay ? 'id' and (not p_data ? 'id' or p_data->>'id'=replay->>'id') then p_data:=p_data||jsonb_build_object('id',replay->'id','version',replay->'version');end if;
   else
    if not wash_private.edit_evaluation(eid) then raise exception 'FORBIDDEN' using errcode='42501';end if;
    if r.id is not null then select * into r from public.wash_records where id=r.id for update;else select * into r from public.wash_records where evaluation_id=eid and kind='indicator' and record_key=p_data->>'record_key' for update;end if;
    if r.id is not null then p_data:=p_data||jsonb_build_object('id',r.id,'version',r.version);end if;
   end if;
  end if;
 end if;
 return wash_private.command_before_completion(p_command,p_data,p_operation);
end $$;
revoke all on function wash_private.command(text,jsonb,uuid) from public,anon,service_role;
grant execute on function wash_private.command(text,jsonb,uuid) to authenticated;
